def longestWPI(hours: list[int]) -> int:
    res = curr = 0
    seen = {}
    for i, h in enumerate(hours):
        curr += (1 if h > 8 else -1)
        if curr > 0:
            res = i + 1
        else:
            if curr not in seen:
                seen[curr] = i
            if curr - 1 in seen:
                res = max(res, i - seen[curr - 1])
    return res

